mapper.select:
SELECT id,conversation_id,role,content,request_id,trace_id,status,error_code,confidence_level,
faithfulness_status,input_tokens,output_tokens,created_at,verification_details::text AS verification_json,
(SELECT CASE WHEN count(*) FILTER(WHERE estimated_cost IS NULL)=0 THEN sum(estimated_cost) END
FROM ai_usage u
WHERE u.request_id=chat_message.request_id) AS estimated_cost
FROM chat_message
WHERE conversation_id=#{id}
ORDER BY id
LIMIT #{limit}
OFFSET #{offset}

SELECT id,title,created_at,updated_at
FROM conversation
WHERE user_id=#{user} AND NOT deleted
ORDER BY updated_at DESC,id DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT m.knowledge_base_ids::text AS scope_json,m.retrieval_trace::text AS trace_json
FROM chat_message m JOIN conversation c ON c.id=m.conversation_id AND NOT c.deleted
WHERE m.request_id=#{request} AND m.role='ASSISTANT' AND m.user_id=#{user} AND c.user_id=#{user}

mapper.update:
UPDATE chat_message
SET content=#{content},status=#{status},error_code=#{error}, input_tokens=#{input},output_tokens=#{output}
WHERE id=#{id} AND status='GENERATING'

UPDATE conversation
SET title=#{title}
WHERE id=#{id} AND user_id=#{user} AND NOT deleted

UPDATE chat_message
SET content=#{content}
WHERE id=#{id} AND status='GENERATING'

UPDATE conversation
SET updated_at=clock_timestamp()
WHERE id=#{id}

mapper.select:
SELECT count(*)
FROM chat_message
WHERE conversation_id=#{id}

mapper.update:
UPDATE message_citation
SET evidence_content=#{content},source_metadata=CAST(#{metadata} AS jsonb)
WHERE message_id=#{message} AND citation_id=#{citation}
